import re, sys, zlib

path = sys.argv[1]
needle = sys.argv[2].lower()
data = open(path, 'rb').read()

texts = []
for m in re.finditer(rb'stream\r?\n', data):
    start = m.end()
    end = data.find(b'endstream', start)
    if end == -1:
        continue
    raw = data[start:end]
    try:
        out = zlib.decompress(raw)
    except Exception:
        try:
            out = zlib.decompressobj().decompress(raw)
        except Exception:
            continue
    texts.append(out)

blob = b'\n'.join(texts)

# pull literal strings out of content streams
lines = []
cur = []
for tok in re.finditer(rb'\((?:\\.|[^()\\])*\)|TJ|Tj|T\*|Td|TD|ET', blob):
    t = tok.group()
    if t.startswith(b'('):
        s = t[1:-1]
        s = re.sub(rb'\\([()\\])', rb'\1', s)
        cur.append(s.decode('latin-1'))
    elif t in (b'T*', b'Td', b'TD', b'ET'):
        if cur:
            lines.append(''.join(cur))
            cur = []
if cur:
    lines.append(''.join(cur))

for i, ln in enumerate(lines):
    if needle in ln.lower():
        lo = max(0, i - 4)
        hi = min(len(lines), i + 12)
        print('--- match at line %d ---' % i)
        for j in range(lo, hi):
            print('%6d | %s' % (j, lines[j]))
        print()
